function library(){host.querySelector(".flow-editor")?.remove();const form=el("div",null,"flow-editor");host.append(form);title(form,"คลังถังและกลไกสำเร็จรูป");note(form,"เลือกเฉพาะชุดที่ต้องการ ไม่ทับถังเดิมหรือคะแนนเดิม ค่าตั้งต้นและเกณฑ์เป็นตัวอย่างแก้ได้");const current=DB();for(const p of presets()){if(owner!=="shared")p.v.id=owner+"_"+p.v.id;const r=row(form),exists=current.variables.some(v=>v.id===p.v.id);const add=button(exists?"ใช้แล้ว":"เพิ่มชุดนี้",()=>{install([p]);sharedEngine(host,api);library()});add.disabled=exists;r.append(el("strong",p.v.name+" · "+E.types[p.v.type]),el("span",p.tests.map(t=>t[0]).join(" / ")||"สร้างถังสำหรับตั้งเงื่อนไขเอง"),add)}form.prepend(button("เพิ่มทุกชุดที่ยังไม่มี",()=>{if(confirm("เพิ่มชุดสำเร็จรูปทั้งหมดที่ยังไม่มี? ไม่แก้ค่าเดิม")){install(presets().map(p=>({...p,v:{...p.v,id:owner==="shared"?p.v.id:owner+"_"+p.v.id}})));sharedEngine(host,api)}},"on"));form.append(button("ปิด",()=>form.remove()))}
